/* 修复前——<i> 默认 inline，width/height 全部失效 */
.fill{height:100%;width:0;background:var(--teal);
      transition:width 1.2s cubic-bezier(.2,.8,.2,1)}

/* 修复后——补一个 display，条形才有盒子 */
.fill{display:block;height:100%;width:0;
      background:var(--teal);transition:width 1.2s …}

# 顺手把它写进 shell 闸门签名，防止再漏
("条形填充可见", "display:block;height:100%;width:0")
